+    private static void testListRemoveAt(List<Integer> list) {
+        int index = list.size() / 2;
+        List<Integer> expected = new ArrayList<>(list);
+        Integer removed = expected.remove(index);
+
+        equal(list.removeAt(index), removed);
+        equal(list, expected);
+    }
